def transform(grid):
    h,w=len(grid),len(grid[0]); seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
        if grid[r][c] and (r,c) not in seen:
          st=[(r,c)]; seen.add((r,c)); comp=[]
          while st:
            x,y=st.pop(); comp.append((x,y))
            for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
              a,b=x+dx,y+dy
              if 0<=a<h and 0<=b<w and grid[a][b] and (a,b) not in seen:
                seen.add((a,b));st.append((a,b))
          comps.append(comp)
    target=min(comps,key=lambda comp:sum(grid[r][c]==9 for r,c in comp))
    out=[row[:] for row in grid]
    for r,c in target: out[r][c]=0
    return out
